#!/usr/bin/env python3
from pathlib import Path
import argparse,hashlib,json,subprocess
ROOT=Path(__file__).resolve().parents[1];p=argparse.ArgumentParser();p.add_argument('--out',type=Path,required=True);p.add_argument('--execute',action='store_true');p.add_argument('--native',action='store_true');a=p.parse_args();out=a.out.resolve();out.relative_to(ROOT/'results');assert not out.exists();out.mkdir();commands=[]
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def run(argv,label):
 r=subprocess.run(argv,cwd=ROOT,capture_output=True,text=True,timeout=45);(out/(label+'.stdout')).write_text(r.stdout);(out/(label+'.stderr')).write_text(r.stderr);commands.append({'label':label,'argv':argv,'exit_code':r.returncode});(out/'commands.json').write_text(json.dumps(commands,indent=2)+'\n');print(label,r.returncode,flush=True);assert r.returncode==0,r.stderr[-2300:]
sources=[]
for folder,n in [('src','KeplerCPUICB.h'),('src','KeplerCPUICB.mm'),('src','KeplerNativeCommands.h'),('src','KeplerNativeCommands.mm'),('src','KeplerNativeRenderDraws.h'),('src','KeplerNativeRenderDraws.mm'),('src','cpu_icb_depth_gpu_profiles.json'),('src','cpu_icb_stencil_writer_profiles.json'),('src','gpu_argument_selector.metal'),('src','private_argument_selector.metal'),('tools','cpu_icb_depth_gpu_probe.mm'),('tools','verify_cpu_icb_depth_gpu.py'),('tools','verify_native_gpu_argument_choice.py'),('tools','verify_cpu_icb_combined.py'),('tools','decode_native_commands.py')]:
 f=out/n;f.write_bytes((ROOT/folder/n).read_bytes());sources.append(f)
(out/Path(__file__).name).write_bytes(Path(__file__).read_bytes());copies=[('gpu-argument-selector-passive','gpu_argument_selector.metallib'),('native-combined-arguments-passive','combined_render_resources.metallib'),('render-state-final','render_state_carrier.metallib')]
for directory,n in copies:(out/n).write_bytes((ROOT/'results'/directory/n).read_bytes())
(out/'inputs.json').write_text(json.dumps({'source_hashes':{f.name:sha(f) for f in sources},'library_SHA256':sha(out/'combined_render_resources.metallib'),'selector_library_SHA256':sha(out/'gpu_argument_selector.metallib'),'manifest_SHA256':sha(out/'cpu_icb_depth_gpu_profiles.json'),'Git_commit':None,'Qwen_job_ids':[],'system_modified':False},indent=2)+'\n');exe=out/'cpu_icb_depth_gpu_probe';run(['clang++','-O2','-std=c++17','-fobjc-arc','-I',str(out),str(out/'cpu_icb_depth_gpu_probe.mm'),str(out/'KeplerCPUICB.mm'),str(out/'KeplerNativeCommands.mm'),str(out/'KeplerNativeRenderDraws.mm'),'-framework','Metal','-framework','Foundation','-o',str(exe)],'build');raw=out/'outputs';raw.mkdir();run(['python3',str(ROOT/'tools/run_signed_probe.py'),'--exe',str(exe),'--out',str(out/'execution'),'--timeout','30','--',str(out/'render_state_carrier.metallib'),str(out/'combined_render_resources.metallib'),str(out/'cpu_icb_depth_gpu_profiles.json'),str(out/'gpu_argument_selector.metallib'),str(raw),('native-' if a.native else 'icb-')+('execute' if a.execute else 'prepare')],'observe');m=json.loads((out/'execution/manifest.json').read_text());assert m['exit_code']==0 and not m['SIGKILL_requested'] and not m['authoritative_ps_status'];d=json.loads((out/'execution/execution.stdout').read_text());assert d['passed'];(out/'results.json').write_text(json.dumps(d,indent=2)+'\n');print(json.dumps({'mode':d['mode'],'trials':len(d['runs']),'scope_restored':d['scope_restored'],'all_children_terminal':True}))
